    65	  enum Flag {
    66	    // Regular flags
    67	    Updated,     // Entry was modified
    68	    Parsing,     // Entry is currently being parsed
    69	
    70	    // Special flags -- available only after xref->scanSpecialFlags() is run
    71	    Unencrypted, // Entry is stored in unencrypted form (meaningless in unencrypted documents)
    72	    DontRewrite  // Entry must not be written back in case of full rewrite
    73	  };
    74	
    75	  inline bool getFlag(Flag flag) const {
    76	    const int mask = (1 << (int)flag);
    77	    return (flags & mask) != 0;
    78	  }
    79	
    80	  inline void setFlag(Flag flag, bool value) {
    81	    const int mask = (1 << (int)flag);
    82	    if (value) {
    83	      flags |= mask;
    84	    } else {
    85	      flags &= ~mask;
    86	    }
    87	  }
    88	};
